// Build a structured prompt for the LLM

const commits = $input.all()[0]?.json?.commits || [];
const issues = $input.all()[1]?.json?.issues || [];
const prs = $input.all()[2]?.json?.prs || [];
const config = $input.all()[3]?.json || {};

const repo = config.repo || 'unknown/repo';
const lang = (config.language || 'EN').toUpperCase();

const weekStart = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const weekAgo = weekStart.toISOString().split('T')[0];

// Filter merged PRs (those with merged_at)
const mergedPRs = (prs || []).filter(p => p.merged_at && new Date(p.merged_at) > weekStart);

// Filter closed issues (exclude PRs)
const closedIssues = (issues || []).filter(i => !i.pull_request && new Date(i.closed_at) > weekStart);

// Count contributors
const contributors = new Set();
(commits || []).forEach(c => contributors.add(c.commit?.author?.name || c.author?.login));
(mergedPRs || []).forEach(p => contributors.add(p.user?.login));

const summary = {
  repo,
  week: weekAgo,
  stats: {
    commits: (commits || []).length,
    closedIssues: closedIssues.length,
    mergedPRs: mergedPRs.length,
    contributors: contributors.size
  },
  topCommits: (commits || []).slice(0, 15).map(c => ({
    message: c.commit?.message?.split('\n')[0],
    author: c.commit?.author?.name || c.author?.login,
    date: c.commit?.author?.date?.split('T')[0]
  })),
  closedIssues: closedIssues.slice(0, 10).map(i => ({
    title: i.title,
    number: i.number,
    author: i.user?.login
  })),
  mergedPRs: mergedPRs.slice(0, 10).map(p => ({
    title: p.title,
    number: p.number,
    author: p.user?.login
  }))
};

let prompt;
if (lang === 'FR') {
  prompt = `Résumé hebdomadaire du développement — ${repo} (semaine du ${weekAgo})\n\n### Statistiques\n- Commits: ${summary.stats.commits}\n- Issues fermées: ${summary.stats.closedIssues}\n- PRs fusionnées: ${summary.stats.mergedPRs}\n- Contributeurs: ${summary.stats.contributors}\n\n### Commits récents\n${summary.topCommits.map(c => `- ${c.message} (${c.author}, ${c.date})`).join('\n')}\n\n### Issues fermées\n${summary.closedIssues.map(i => `- #${i.number}: ${i.title} (${i.author})`).join('\n') || 'Aucune'}\n\n### PRs fusionnées\n${summary.mergedPRs.map(p => `- #${p.number}: ${p.title} (${p.author})`).join('\n') || 'Aucune'}\n\nGénère un résumé narratif en français (3-5 paragraphes) mettant en évidence les changements importants, les tendances et les points d'attention.`;
} else {
  prompt = `Weekly Development Summary — ${repo} (week of ${weekAgo})\n\n### Stats\n- Commits: ${summary.stats.commits}\n- Closed Issues: ${summary.stats.closedIssues}\n- Merged PRs: ${summary.stats.mergedPRs}\n- Contributors: ${summary.stats.contributors}\n\n### Recent Commits\n${summary.topCommits.map(c => `- ${c.message} (${c.author}, ${c.date})`).join('\n')}\n\n### Closed Issues\n${summary.closedIssues.map(i => `- #${i.number}: ${i.title} (${i.author})`).join('\n') || 'None'}\n\n### Merged PRs\n${summary.mergedPRs.map(p => `- #${p.number}: ${p.title} (${p.author})`).join('\n') || 'None'}\n\nGenerate a narrative summary in English (3-5 paragraphs) highlighting key changes, trends, and areas needing attention.`;
}

return [{ prompt, repo, language: lang, webhookUrl: config.webhookUrl }];

// Extract the LLM response
const response = $input.first().json;

let narrative = '';
try {
  narrative = response.choices?.[0]?.message?.content || response.content || JSON.stringify(response);
} catch(e) {
  narrative = 'Failed to parse LLM response: ' + e.message;
}

const repo = $input.first().json.repo || 'unknown/repo';
const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

const message = `📊 *Weekly Dev Summary — ${repo}*\n📅 Week of ${weekAgo}\n\n${narrative}\n\n---\n_Generated by n8n Weekly Dev Summary workflow_`;

return [{ message, repo, weekAgo }];
